import { Project } from '../../src'

describe('property assignment tests', () => {
    test.skip('stringify the properties if required', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: '12345' },
        })

        // TODO: The XML parser won't even allow elements that start with numbers, so not sure what we should be testing here
        const { changedFiles } = await project.transform({
            path: 'update_file.xml',
            content: `
<?xml version="1.0"?>
<record_update sys_domain="global" table="test_table">
    <test_table action="INSERT_OR_UPDATE">
        <sys_id>4faea290dbe304104168f6c5ae9619c4</sys_id>
        <0stringifyme>I'm stringified</0stringifyme>
        <do_not_stringify>I'm not</do_not_stringify>
    </test_table>
</record_update>
`,
        })

        expect(changedFiles).toHaveLength(1)
        expect(changedFiles[0].getContent()).toEqual(
            `import { Record } from "@servicenow/sdk/core";

export default Record({
    $id: "4faea290dbe304104168f6c5ae9619c4",
    table: "test_table",
    data: {
        "0stringifyme": "I'm stringified",
        do_not_stringify: "I'm not"
    }
});
`
        )
    })

    test.skip('stringify the properties with spaces', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: '12345' },
        })

        const { changedFiles } = await project.transform({
            path: 'update_file.xml',
            content: `
<?xml version="1.0"?>
<database>
  <element name="sn_table_app_incoming" extends="cmdb" type="collection" label="Incoming Table" attributes="other=true">
    <element name="string_column" type="string" attributes="update_sync=false" audit="false" label="string_column" read_only="false" choice="0" display="false">
      <choice>
        <element value="with space" label="choice1"/>
      </choice>
    </element>
  </element>
</database>
`,
        })

        expect(changedFiles).toHaveLength(1)

        // FIXME: Table plugin isn't generating the right code here
        expect(changedFiles[0].getContent()).toEqual(
            `import { Table, StringColumn } from '@servicenow/sdk/core'

export const sn_table_app_incoming = Table({
    attributes: {
        other: true,
    },
    extends: 'cmdb',
    label: 'Incoming Table',
    name: 'sn_table_app_incoming',
    schema: {
        string_column: StringColumn({
            read_only: false,
            attributes: {
                update_sync: false,
            },
            dropdown: 'none',
            audit: false,
            choices: {
                'with space': {
                    label: 'choice1',
                },
            },
        }),
    },
})
`
        )
    })
})
